import test from 'node:test'; import assert from 'node:assert/strict'; import { mkdtemp, rm } from 'node:fs/promises'; import os from 'node:os'; import path from 'node:path'; import { append, read } from '../src/ledger.mjs'; test('ledger roundtrip', async t => { const root = await mkdtemp(path.join(os.tmpdir(), 'ledger-fixture-')); t.after(() => rm(root, { recursive: true, force: true })); const file = path.join(root, 'events'); await append(file, { id: 'a', amount: 3 }); assert.deepEqual(await read(file), [{ id: 'a', amount: 3 }]); await assert.rejects(append(file, {}), TypeError); });
